import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const r="/images/logic-studio/user-guide/blocks-js-fr.png",h=JSON.parse('{"title":"Blocks JS","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/blocks-js.md","filePath":"fr/projects/logic-studio/user-guide/blocks-js.md","lastUpdated":1794838137000}'),i={name:"fr/projects/logic-studio/user-guide/blocks-js.md"};function l(n,e,c,u,d,p){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="blocks-js" tabindex="-1">Blocks JS <a class="header-anchor" href="#blocks-js" aria-label="Permalink to &quot;Blocks JS&quot;">​</a></h1><h2 id="premier-exemple" tabindex="-1">Premier exemple <a class="header-anchor" href="#premier-exemple" aria-label="Permalink to &quot;Premier exemple&quot;">​</a></h2><p>Le test lit l’état simulé d’une entité et l’affiche dans le journal.</p><ol><li>Choisis <strong>Nouveau projet → Blocks JS</strong>. Dans <strong>Système</strong>, glisse le bloc <strong>Journal</strong> sur le canevas.</li><li>Glisse <strong>État de</strong> dans l’entrée libre du bloc de journal. Choisis ton entité de test. La capture utilise <code>binary_sensor.bewegung</code>.</li><li>Lance un <strong>test</strong> et consulte le <strong>journal</strong>. La démonstration affiche l’état et le message <code>on</code>. Le script lit et affiche la valeur.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-js-fr.png"><img src="'+r+'" alt="Blocks JS avec un bloc d’état relié au journal"></a></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="systeme-actions-et-sendto" tabindex="-1">Système, actions et Sendto <a class="header-anchor" href="#systeme-actions-et-sendto" aria-label="Permalink to &quot;Système, actions et Sendto&quot;">​</a></h3><p>Lis des états, commande des cibles autorisées, envoie des messages ou consulte l’historique. Une entrée dynamique peut accepter un identifiant obtenu dans une boucle.</p><h3 id="declencheurs-temps-et-temporisations" tabindex="-1">Déclencheurs, temps et temporisations <a class="header-anchor" href="#declencheurs-temps-et-temporisations" aria-label="Permalink to &quot;Déclencheurs, temps et temporisations&quot;">​</a></h3><p>Démarre sur changement d’état, événement solaire ou horaire. Utilise des règles CRON simples ou nommées, des délais, des intervalles et leurs blocs d’arrêt.</p><h3 id="blocs-de-valeurs" tabindex="-1">Blocs de valeurs <a class="header-anchor" href="#blocs-de-valeurs" aria-label="Permalink to &quot;Blocs de valeurs&quot;">​</a></h3><p>Les catégories conversion, objet, logique, mathématiques, texte, listes et couleur produisent des valeurs. Les boucles répètent des opérations.</p><h3 id="variables-et-fonctions" tabindex="-1">Variables et fonctions <a class="header-anchor" href="#variables-et-fonctions" aria-label="Permalink to &quot;Variables et fonctions&quot;">​</a></h3><p>Les variables conservent des valeurs intermédiaires. Les fonctions regroupent des étapes et peuvent renvoyer une valeur.</p><h3 id="import-iobroker" tabindex="-1">Import ioBroker <a class="header-anchor" href="#import-iobroker" aria-label="Permalink to &quot;Import ioBroker&quot;">​</a></h3><p>Colle l’export en mode expert et lis le rapport. Associe explicitement les entités et consulte les indications de chaque bloc.</p><h3 id="blocs-http-importes" tabindex="-1">Blocs HTTP importés <a class="header-anchor" href="#blocs-http-importes" aria-label="Permalink to &quot;Blocs HTTP importés&quot;">​</a></h3><p>Choisis une commande REST HA autorisée. Configure l’URL, le délai et les en-têtes dans HA. Le bloc POST indique le Content-Type importé.</p><h3 id="test-et-play" tabindex="-1">Test et Play <a class="header-anchor" href="#test-et-play" aria-label="Permalink to &quot;Test et Play&quot;">​</a></h3><p>Commence par la simulation. Enregistre avant Play et vérifie les résultats réels dans le journal.</p><h2 id="verifier-un-import-etape-par-etape" tabindex="-1">Vérifier un import étape par étape <a class="header-anchor" href="#verifier-un-import-etape-par-etape" aria-label="Permalink to &quot;Vérifier un import étape par étape&quot;">​</a></h2><ol><li>Active le <strong>mode expert</strong> dans le menu du projet. Dans l’éditeur, ouvre les outils experts et choisis l’import ioBroker.</li><li>Colle le XML Blockly ou un export JavaScript ioBroker contenant les données Blockly. Vérifie l’import et repère les blocs à associer.</li><li>Ouvre l’import comme projet et suis les indications affichées sur les blocs concernés. Pour un POST importé, choisis la commande REST HA qui définit les en-têtes et le délai.</li><li>Enregistre et lance d’abord un <strong>test</strong>. Utilise ensuite <strong>Play</strong> pour l’exécution réelle, vérifie le <strong>journal</strong> et termine avec <strong>Stop</strong>.</li></ol><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Adapte les blocs signalés avant l’exécution.</p>',24)])])}const b=t(i,[["render",l]]);export{h as __pageData,b as default};
